-- 01_create_and_load.sql  (MySQL 8 / 9)
-- Run:  mysql -u root -p < 01_create_and_load.sql      (or paste into Workbench and run)

CREATE DATABASE IF NOT EXISTS ds_dept;
CREATE DATABASE IF NOT EXISTS ds_dept_temp;
USE ds_dept;

DROP VIEW  IF EXISTS v_cs_background;   -- harmless if views not created yet
DROP TABLE IF EXISTS students;
DROP TABLE IF EXISTS ug_programs;

-- Lookup table: which "background family" each UG degree belongs to
CREATE TABLE ug_programs (
    ug_degree    VARCHAR(30) PRIMARY KEY,
    stream_group VARCHAR(30) NOT NULL          -- Mathematics / Statistics / Computer Science / Data Science
);


CREATE TABLE students (
    student_id      INT AUTO_INCREMENT PRIMARY KEY,
    reg_no          VARCHAR(12)  NOT NULL UNIQUE,
    first_name      VARCHAR(40)  NOT NULL,
    last_name       VARCHAR(40)  NOT NULL,
    gender          CHAR(1)      NOT NULL,
    dob             DATE         NOT NULL,
    email           VARCHAR(80)  NOT NULL,
    ug_degree       VARCHAR(30)  NOT NULL,
    ug_percentage   DECIMAL(5,2) NOT NULL,
    city            VARCHAR(30)  NOT NULL,
    admission_year  SMALLINT     NOT NULL,
    graduation_year SMALLINT     NULL,          -- expected year for Active students; NULL if Dropped
    status          ENUM('Active','Alumni','Dropped') NOT NULL,
    cgpa            DECIMAL(4,2) NULL,          -- final for Alumni, current for Active, NULL for new batch
    placed_company  VARCHAR(40)  NULL,
    package_lpa     DECIMAL(4,1) NULL,          -- synthetic demo numbers
    INDEX idx_degree (ug_degree),
    INDEX idx_year   (admission_year),
    CONSTRAINT fk_degree FOREIGN KEY (ug_degree) REFERENCES ug_programs (ug_degree)
);





SELECT COUNT(*) AS total_students FROM students;
SELECT admission_year, COUNT(*) AS batch_size FROM students GROUP BY admission_year ORDER BY admission_year;